package org.xingmu.tv;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.*;
public class PlaylistImporterTest {
 @Test public void m3uGroupsAndCountryArePreserved()throws Exception{List<CatalogItem> rows=CatalogParser.parse(PlaylistImporter.convert("#EXTM3U\n#EXTINF:-1 group-title=\"新闻\" tvg-country=\"日本\",NHK\nhttps://example.org/live.m3u8","foreign","未分类"));assertEquals("新闻",rows.get(0).category);assertEquals("日本",rows.get(0).country);}
 @Test public void txtDuplicatesBecomeBackups()throws Exception{List<CatalogItem> rows=CatalogParser.parse(PlaylistImporter.convert("央视,#genre#\nCCTV1,https://example.org/a.m3u8\nCCTV1,https://example.org/b.m3u8\nCCTV1,https://example.org/b.m3u8","domestic","中国"));assertEquals(1,rows.size());assertEquals(2,rows.get(0).urls.size());assertEquals("央视",rows.get(0).category);}
 @Test public void movieDollarFormatIsAccepted()throws Exception{CatalogItem item=CatalogParser.parse(PlaylistImporter.convert("开放电影$https://example.org/a.mp4","films","中国")).get(0);assertEquals("开放电影",item.title);assertFalse(item.live());}
 @Test public void namespacedXspfIsSupported()throws Exception{CatalogItem item=CatalogParser.parse(PlaylistImporter.convert("<playlist xmlns=\"http://xspf.org/ns/0/\"><trackList><track><title>戏曲</title><album>京剧</album><location>https://example.org/a.mp4</location></track></trackList></playlist>","films","中国")).get(0);assertTrue(item.opera());}
 @Test(expected=IOException.class) public void xmlEntitiesAreRejected()throws Exception{PlaylistImporter.convert("<!DOCTYPE playlist [<!ENTITY secret SYSTEM 'file:///etc/passwd'>]><playlist><track><title>&secret;</title><location>https://example.org/a</location></track></playlist>","films","中国");}
 @Test(expected=IOException.class) public void rawHlsManifestCannotBeImportedAsChannels()throws Exception{PlaylistImporter.convert("#EXTM3U\n#EXT-X-TARGETDURATION:10\n#EXTINF:10\nhttps://example.org/segment.ts","domestic","中国");}
 @Test(expected=IOException.class) public void localAddressIsRejected()throws Exception{PlaylistImporter.convert("local,https://127.0.0.1/a","domestic","中国");}
 @Test public void repeatImportHasStableIds()throws Exception{String input="电影,https://example.org/a.mp4";assertEquals(CatalogParser.parse(PlaylistImporter.convert(input,"films","中国")).get(0).id,CatalogParser.parse(PlaylistImporter.convert(input,"films","中国")).get(0).id);}
 @Test public void bomAndCrLfAreSupported()throws Exception{assertEquals(1,CatalogParser.parse(PlaylistImporter.convert("\uFEFF#EXTM3U\r\n#EXTINF:-1,电影\r\nhttps://example.org/a.mp4","films","中国")).size());}
 @Test public void publicHttpDirectStreamSupported()throws Exception{assertEquals("http://example.org/live.m3u8",CatalogParser.parse(PlaylistImporter.convert("台,http://example.org/live.m3u8","domestic","中国")).get(0).url);assertFalse(CatalogParser.safeMediaUrl("http://127.0.0.1/a"));assertFalse(CatalogParser.safeMediaUrl("http://user:password@example.org/a"));}
 @Test(expected=IOException.class) public void executableTvboxConfigurationHasClearRejection()throws Exception{PlaylistImporter.convert("{\"spider\":\"plugin.jar\",\"sites\":[]}","films","中国");}
}
